    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0_2).getByTestId("claim-amount")).toHaveText("10.00");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0_2).getByTestId("claim-date")).toHaveText("2026-03-02");
