        return asOf == null ? consolidated.descendantsOf(id.trim()) : consolidated.consolidatedOf(id.trim());
    }

    /** Load a sheet by id, starting it empty if it has never been loaded; as it stood at the end of
     * {@code asOf}, that date standing in for its today, when one is given. */
    @PostMapping("/{id}/load")
    public SheetView load(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        Sheet sheet = service.load(id.trim(), user.trim());
        if (asOf == null) return SheetView.of(sheet);
        SheetAsOf then = history.read(sheet.getId(), asOf);
        return new SheetView(sheet.getId(), asOf, then.archived(), then.lastSettleBatch(), sheet.getParentId());
    }

    /** Change the sheet's today. */
    @PutMapping("/{id}/today")
    public SheetView setToday(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid TodayRequest request) {
        return SheetView.of(service.setToday(id.trim(), user.trim(), request.today()));
    }

    /** Archive the sheet: only a steward may. */
    @PostMapping("/{id}/archive")
    public SheetView archive(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return SheetView.of(service.archive(id.trim(), user.trim()));
    }
}
package net.officefloor.hq.app.sheet;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** The sheets naming {@code parentId} as their parent: its children. */
    List<Sheet> findByParentIdOrderByIdAsc(String parentId);

    /** Advance the sheet's last claim number; the row stays locked until the transaction ends. */
    @Modifying(flushAutomatically = true)
    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = :id", nativeQuery = true)
    int advanceClaimNumber(String id);

    @Query(value = "SELECT last_claim_number FROM sheet WHERE id = :id", nativeQuery = true)
    int lastClaimNumber(String id);

    /** Lock the sheet's row until the transaction ends, so its per-period sequences advance one at a time. */
    @Modifying(flushAutomatically = true)
    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number WHERE id = :id", nativeQuery = true)
    int lockSheet(String id);

    /** Advance the sheet's sequence named {@code key}; 0 when it has not been started. */
    @Modifying(flushAutomatically = true)
    @Query(value = "UPDATE claim_sequence SET last_number = last_number + 1 WHERE sheet_id = :id AND seq_key = :key",
            nativeQuery = true)
    int advanceSequence(String id, String key);

    /** Start the sheet's sequence named {@code key} at 1. */
    @Modifying(flushAutomatically = true)
    @Query(value = "INSERT INTO claim_sequence (sheet_id, seq_key, last_number) VALUES (:id, :key, 1)",
            nativeQuery = true)
    int startSequence(String id, String key);

    @Query(value = "SELECT last_number FROM claim_sequence WHERE sheet_id = :id AND seq_key = :key", nativeQuery = true)
    int lastInSequence(String id, String key);
}
package net.officefloor.hq.app.audit;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The audit lines a sheet's viewer shows, read from the audit file as it holds them. */
@Service
public class AuditService {

    private final Audit audit;
    private final PersonRepository people;

    public AuditService(Audit audit, PersonRepository people) {
        this.audit = audit;
        this.people = people;
    }

    /**
     * The sheet's lines, newest first, or (with a name) only those about that person; when the person
     * so named on the sheet was transferred to it, followed by the lines about them from the sheet they
     * came from, newest first, as that sheet's lines hold them.
     */
    @Transactional(readOnly = true)
    public List<String> lines(String sheetId, String name) {
        List<String> lines = new ArrayList<>(audit.lines(sheetId, name));
        if (name != null && !name.isBlank()) {
            people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
                    .map(Person::getOriginSheetId)
                    .ifPresent(origin -> lines.addAll(audit.lines(origin, name)));
        }
        return lines;
    }
}

# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
== V1__sheet.sql
-- A sheet: everything else in the app is kept per sheet, keyed by its id.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP    NOT NULL
);
== V2__sheet_today.sql
-- Each sheet's own "today": every date-dependent decision and default date uses it, never the
-- real clock. It starts as the real date the sheet was first loaded.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- People on a sheet, listed in the order they were added (their id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on its sheet, compared without regard to case and ignoring the spaces
-- around it. Names are kept with those spaces removed; name_key is the name as compared.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200);
UPDATE person SET name_key = LOWER(name);
ALTER TABLE person ALTER COLUMN name_key SET NOT NULL;
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== V5__claim.sql
-- Claims a person makes, listed under the person newest first (their id). The amount is 0.00 or
-- more with up to two decimals; the date defaults to the sheet's today; the note may be empty.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(500)   NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
CREATE INDEX claim_person ON claim (person_id, id);
== V6__rate.sql
-- Each sheet's rate for a grade: a percent, 0.00 or more with two decimals. A grade with no row has
-- no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL,
    pct      DECIMAL(7, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
== V7__claim_status.sql
-- A claim's status: DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID.
-- Only OPEN and SETTLED claims count toward what is claimed and due.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_status CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
== V8__claim_number.sql
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), never reused.
-- A DRAFT claim has none; voiding a claim clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
ALTER TABLE claim ADD CONSTRAINT claim_number_unique UNIQUE (sheet_id, claim_number);
== V9__claim_settled_due.sql
-- What was due on a claim when it was settled, at its person's rate then; later rate changes leave
-- it as it is. Null until the claim is settled, and when its person's grade had no rate then (no
-- figure is fixed, so what is due on it follows the rate).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(12, 2);
== V10__rate_from.sql
-- A rate applies from its from-date on; a rate with no from-date applies from the beginning of
-- time. A grade may have several rates, one per from-date (one with none).
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE UNIQUE NULLS NOT DISTINCT INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_date);
== V11__claim_opened_by.sql
-- Who opened a claim; null while it has not been opened. The user who opened a claim cannot settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
== V12__person_version.sql
-- The version of a person, raised each time they are saved, so an editor that loaded an older
-- version is refused instead of overwriting another user's save.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
== V13__claim_stated.sql
-- Whether a claim is bound to the figure it had at its person's last statement, and that figure.
-- A bound claim shows and totals stated_due whatever later rate or grade changes would make it,
-- until the person's next statement rebinds (or, when the claim no longer counts, unbinds) it.
-- stated_due is null when the claim is unbound, and when it had no figure (no rate) when stated.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(12, 2);
== V14__statement.sql
-- The statements taken of a person: the sheet's today when each was taken, the person's due-total
-- then and how many of their claims counted toward it.
CREATE TABLE statement (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id      BIGINT         NOT NULL REFERENCES person (id),
    statement_date DATE           NOT NULL,
    due_total      DECIMAL(14, 2) NOT NULL,
    claim_count    INT            NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet_id, id);
== V15__statement_due_total_none.sql
-- A statement's due-total is null when the person's due-total was n/a then (no claim with a figure
-- and no rate of their grade in force on the sheet's today).
ALTER TABLE statement ALTER COLUMN due_total SET NULL;
== V16__period.sql
-- A sheet's periods: a name, unique on the sheet without regard to case (name_key is the name as
-- compared), and a from and to date, both inclusive. No two periods of a sheet overlap.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    name_key  VARCHAR(100) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
== V17__period_closed.sql
-- Whether a period is closed, and its due-total fixed when it was closed; later rate changes leave
-- that total as it is. No claim dated in a closed period can be added, edited or change status.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(12, 2);
== V18__person_retired.sql
-- The date a person is retired from; null while they are not retired. A person with the date set
-- is retired at once, whatever the date; claims dated after it are refused.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V19__person_held.sql
-- Whether a person is on hold. While held, their OPEN claims count in no live total (their own,
-- the sheet's or a period's); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
== V20__roles_clerk_limit.sql
-- The role each user name has on a sheet: CLERK or STEWARD. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('CLERK', 'STEWARD'))
);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);

-- The most a clerk may settle a claim for: its due must be at or below it. Null means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(12, 2) CHECK (clerk_limit >= 0);
== V21__sheet_floor.sql
-- The least a claim's live due can be: a due worked out at a rate below it is raised to it. A
-- figure already fixed (settled, bound by a statement, a closed period's total) is left as it was.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(12, 2) DEFAULT 1.00 NOT NULL CHECK (due_floor >= 0);
== V22__sheet_terms.sql
-- The sheet's terms: how many days after its date a claim is due by. An OPEN claim whose due-by is
-- before the sheet's today is overdue.
ALTER TABLE sheet ADD COLUMN terms INTEGER DEFAULT 14 NOT NULL CHECK (terms >= 0);
== V23__sheet_late_pct.sql
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every full
-- 30 days it is overdue. A settled claim keeps the charge it had when it was settled.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(12, 2) DEFAULT 0.00 NOT NULL CHECK (late_pct >= 0);
== V24__person_patron.sql
-- The patrons a person has named: other people on the same sheet, each at most once.
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CONSTRAINT person_patron_unique UNIQUE (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
== V25__person_grade_dated.sql
-- The grades a person has been given, each from a date: the one with the latest from-date on or
-- before a date is in force then; the first one given (no from-date) applies from the beginning of time.
CREATE TABLE person_grade (
    person_id  BIGINT     NOT NULL REFERENCES person (id),
    grade      VARCHAR(1) NOT NULL,
    grade_from DATE
);
CREATE INDEX person_grade_person ON person_grade (person_id);
INSERT INTO person_grade (person_id, grade, grade_from) SELECT id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
== V26__claim_corrects.sql
-- A claim with a negative amount is a correction: it carries in corrects the number of the SETTLED
-- claim of the same person it corrects; corrects is null on any other claim.
ALTER TABLE claim ADD COLUMN corrects INTEGER;

-- The amount was checked to be 0.00 or more by an unnamed constraint: replace the column (which drops
-- that constraint) so only a correction can be negative.
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(12, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_amount_correction CHECK (amount >= 0 OR corrects IS NOT NULL);
== V27__sheet_policy_date.sql
-- The sheet's policy date: a claim dated before it rounds its live figures half up, one dated on or
-- after it half to even (a correction by the date of the claim it corrects). Null means the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
== V28__period_numbering.sql
-- The sheet's period numbering from: while it is set and the sheet's today is on or after it, a claim
-- opened is numbered within the period its date falls in (<period name>-<n>), or X-<n> when it falls in
-- none. Null means off. Claim numbers (and the numbers corrections name) are therefore text.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(120);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(120);

-- The last number given in each per-period sequence of a sheet: seq_key is period:<period id>, or none
-- for the claims dated in no period.
CREATE TABLE claim_sequence (
    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet (id),
    seq_key     VARCHAR(40)  NOT NULL,
    last_number INT          NOT NULL,
    PRIMARY KEY (sheet_id, seq_key)
);
== V29__claim_pending.sql
-- A clerk's settle of a claim whose due is above the clerk limit leaves it PENDING until a steward
-- approves it (SETTLED) or rejects it (back to OPEN). A PENDING claim counts like an OPEN one.
ALTER TABLE claim DROP CONSTRAINT claim_status;
ALTER TABLE claim ADD CONSTRAINT claim_status CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
== V30__claim_listed.sql
-- A claim's place in its sheet's list, newest first: the claims are listed by it, highest first. A
-- claim is given the next value of its sheet's listed sequence when it is added, and again when it is
-- moved to another person, so a moved claim is listed as its new person's newest whatever its date.
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;

-- Start each sheet's listed sequence above the claims it already has.
INSERT INTO claim_sequence (sheet_id, seq_key, last_number)
    SELECT sheet_id, 'listed', MAX(id) FROM claim GROUP BY sheet_id;
== V31__grade_terms_claim_due_by.sql
-- A grade's own terms on a sheet: how many days after its date a claim of a person of that grade is
-- due by. A grade with no row uses the sheet's terms.
CREATE TABLE sheet_grade_terms (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL,
    terms    INTEGER      NOT NULL CHECK (terms >= 0)
);
CREATE UNIQUE INDEX sheet_grade_terms_sheet_grade ON sheet_grade_terms (sheet_id, grade);

-- A claim's due-by, fixed when it is added: its date plus the terms of its person's grade in force
-- on that date. It does not follow later changes to the terms or to the claim's date. The claims
-- already kept are given their date plus their sheet's terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = c.sheet_id), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V32__claim_log.sql
-- A claim's status log: one line per status it has had, in the order it had them, with the user who
-- made the change, the sheet's today then and what was due on the claim as it showed then (null when
-- it had no figure). Claims added before the log was kept start with no lines.
CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    claim_id  BIGINT         NOT NULL REFERENCES claim (id),
    status    VARCHAR(20)    NOT NULL,
    by_user   VARCHAR(100)   NOT NULL,
    log_date  DATE           NOT NULL,
    due       DECIMAL(14, 2)
);
CREATE INDEX claim_log_claim ON claim_log (claim_id, id);
== V33__person_hold_interval.sql
-- The holds a person has been put on, each from a date and, optionally, to one (both included): an
-- OPEN or PENDING claim of theirs dated within a hold counts in no live total, unless a statement
-- binds it. A person held before holds had dates keeps a hold from the beginning of time, with no end.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    hold_from DATE   NOT NULL,
    hold_to   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, hold_from, hold_to) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V34__rate_to.sql
-- A rate may also have a to-date: it applies through it (included). A rate with none applies on with
-- no end.
ALTER TABLE rate ADD COLUMN to_date DATE;
== V35__sheet_cap.sql
-- The most a person's due-total can be: a sum of their figures above it shows the cap, and the
-- difference as their excess. Null means no cap.
ALTER TABLE sheet ADD COLUMN due_cap DECIMAL(12, 2) CHECK (due_cap >= 0);
== V36__period_person_total.sql
-- Each person's due-total for a closed period, fixed when it was closed: what is due on their
-- counting claims dated in it. A person with no row here shows 0.00 for the closed period. The
-- rows are removed when the period is reopened.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    total     DECIMAL(12, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
== V37__sheet_setting_dated.sql
-- A sheet's settings that carry a figure, each recorded from a date: the floor, the late percent, the
-- terms (the sheet's, and each grade's as terms-<grade>), the clerk limit and the cap. The value in
-- force on a date is the one with the latest from-date on or before it; before every from-date it is
-- the sheet's starting value (floor 1.00, late percent 0.00, terms 14; none for the others). A null
-- value records "none" from that date: no clerk limit, no cap, or a grade using the sheet's terms.
CREATE TABLE sheet_setting (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(20)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(20)
);
CREATE UNIQUE INDEX sheet_setting_sheet_key_from ON sheet_setting (sheet_id, setting_key, from_date);

-- The values already kept are in force from the beginning of time.
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'floor', DATE '0001-01-01', CAST(due_floor AS VARCHAR) FROM sheet WHERE due_floor <> 1.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'late-pct', DATE '0001-01-01', CAST(late_pct AS VARCHAR) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'terms', DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet WHERE terms <> 14;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'clerk-limit', DATE '0001-01-01', CAST(clerk_limit AS VARCHAR) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'cap', DATE '0001-01-01', CAST(due_cap AS VARCHAR) FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, 'terms-' || grade, DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet_grade_terms;

DROP TABLE sheet_grade_terms;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN terms;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN due_cap;
== V38__claim_deferred.sql
-- The date an OPEN claim is deferred until: until the sheet's today reaches it the claim counts in no
-- total, is not overdue, cannot be settled and no statement binds it. Null on a claim never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V39__claim_proofs.sql
-- How many proofs a claim has been given; raised by one at a time while it is neither SETTLED nor VOID.
-- The sheet's proof threshold is a dated setting (proof-threshold) kept in sheet_setting.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
== V40__sheet_permission.sql
-- The sheet's permission matrix: for an action (open, settle, void, reassign, close, reopen), the roles
-- that may take it, as a comma separated list of lower-case roles. Not dated. An action with no row, or
-- a blank list, keeps the standing rule: open, settle, void and close by clerk and steward; reassign and
-- reopen by steward.
CREATE TABLE sheet_permission (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    perm_action VARCHAR(20)  NOT NULL,
    roles     VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX sheet_permission_sheet_action ON sheet_permission (sheet_id, perm_action);
== V41__role_viewer.sql
-- A third role, VIEWER: sees the sheet and may change nothing. The role's check is rebuilt to allow it.
CREATE TABLE sheet_role_new (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('CLERK', 'STEWARD', 'VIEWER'))
);
INSERT INTO sheet_role_new (id, sheet_id, user_name, role) SELECT id, sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
ALTER TABLE sheet_role ALTER COLUMN id RESTART WITH (SELECT COALESCE(MAX(id), 0) + 1 FROM sheet_role);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);
== V42__sheet_grace_days.sql
-- The sheet's grace days: when its today is changed, every open period whose to-date plus them is
-- before the new today is closed. Null means off.
ALTER TABLE sheet ADD COLUMN grace_days INTEGER;
== V43__claim_split_from.sql
-- A claim split off another carries in split_from the number of the claim it was split from; null on
-- any other claim.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(120);
== V44__person_watch.sql
-- The people each user watches on a sheet, each at most once per user, in the order they started
-- watching: a watched person's claim settled, approved or re-settled notifies each watcher.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(100) NOT NULL,
    CONSTRAINT person_watch_unique UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
== V45__sheet_delegation.sql
-- The steward role delegated by a steward to a user on a sheet, from a from-date to a to-date
-- inclusive: while the sheet's today is inside the range the user acts as a steward.
CREATE TABLE sheet_delegation (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    delegator VARCHAR(100) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (to_date >= from_date)
);
CREATE INDEX sheet_delegation_sheet_user ON sheet_delegation (sheet_id, user_name);
== V46__sheet_archived.sql
-- Whether the sheet is archived: once it is, every change asked of it is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
== V47__person_terms.sql
-- A person's own terms: how many days after its date a claim of theirs is due by, in place of the
-- terms of their grade and the sheet's; null when they have none.
ALTER TABLE person ADD COLUMN terms INTEGER CHECK (terms >= 0);
== V48__claim_lock.sql
-- A claim's editor, once opened, locks the claim for other users: locked_by is the user holding it and
-- locked_on the sheet's today when it was taken. Null while no one holds it; saving or cancelling the
-- editor, or changing the sheet's today, releases it.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(100);
ALTER TABLE claim ADD COLUMN locked_on DATE;
== V49__period_soft_close.sql
-- Whether a closed period is only soft-closed: its due-total and each person's figure for it are fixed
-- as for a close, but claims dated in it can still be added, edited and change status. A claim added
-- while its period is soft-closed is a late entry.
ALTER TABLE period ADD COLUMN soft BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
== V50__claim_stated_by.sql
-- The statement that bound a claim to stated_due; null while the claim is unbound. Cancelling a
-- person's last statement unbinds the claims it bound.
ALTER TABLE claim ADD COLUMN stated_by BIGINT;
== V51__sheet_history.sql
-- Every change to what a sheet's figures are made of (its people, claims, rates, dated settings and
-- the sheet itself), one line per row as it stood after the change, in the order they happened, with
-- the sheet's today when it was made; state is null when the row was removed. A sheet's state as of a
-- date is, for each row, its last line made on or before that date.
CREATE TABLE sheet_history (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL,
    made_on   DATE         NOT NULL,
    entity    VARCHAR(30)  NOT NULL,
    entity_id VARCHAR(100) NOT NULL,
    state     CLOB
);
CREATE INDEX sheet_history_sheet ON sheet_history (sheet_id, made_on, id);
== V52__sheet_entry_date.sql
-- The sheet's entry date: while it is set, a claim added or edited without a date is dated it rather
-- than the sheet's today; null when it is off.
ALTER TABLE sheet ADD COLUMN entry_date DATE;
== V53__claim_reminded.sql
-- The sheet's today on which a reminder was last written for the claim; null when none ever was.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
== V54__sheet_holiday.sql
-- The holidays on a sheet, one row each: a claim's due-by fixed when it is added is moved past them.
CREATE TABLE sheet_holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL,
    CONSTRAINT sheet_holiday_unique UNIQUE (sheet_id, holiday_date)
);
== V55__claim_business_day_terms.sql
-- A claim's terms now count business days. Each claim keeps the terms it was fixed with and the date
-- its due-by counts from (its date when it was added); its due-by is the terms-th business day after
-- that date, skipping weekends and the sheet's holidays. The claims already kept count from their date,
-- with the days their due-by was fixed after it; V56 works their due-by out again in business days.
ALTER TABLE claim ADD COLUMN due_from DATE;
ALTER TABLE claim ADD COLUMN terms INTEGER;
UPDATE claim SET due_from = claim_date, terms = GREATEST(0, DATEDIFF(DAY, claim_date, due_by));
ALTER TABLE claim ALTER COLUMN due_from SET NOT NULL;
ALTER TABLE claim ALTER COLUMN terms SET NOT NULL;
== V57__claim_ref.sql
-- A claim's external reference: null when it has none. Unique on the sheet without regard to case
-- (ref_key is the reference as compared).
ALTER TABLE claim ADD COLUMN ref VARCHAR(120);
ALTER TABLE claim ADD COLUMN ref_key VARCHAR(120);
CREATE UNIQUE INDEX claim_sheet_ref ON claim (sheet_id, ref_key);
== V58__claim_tags.sql
-- A claim's tags: trimmed, lower-cased, without repeats, sorted and comma separated; null when it has
-- none. sheet_tag keeps every tag ever used on a sheet's claims.
ALTER TABLE claim ADD COLUMN tags VARCHAR(1000);
CREATE TABLE sheet_tag (
    sheet_id VARCHAR(100) NOT NULL,
    tag      VARCHAR(500) NOT NULL,
    PRIMARY KEY (sheet_id, tag)
);
== V59__void_reason.sql
-- The reasons a claim can be voided with on a sheet, one row each; while a sheet has any, a void of
-- one of its claims names one of them, kept on the claim (null on a claim voided without one).
CREATE TABLE sheet_void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(200) NOT NULL,
    CONSTRAINT sheet_void_reason_unique UNIQUE (sheet_id, reason)
);
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
== V60__claim_comment.sql
-- A claim's comments, one row each, oldest first by id: the text, the user who wrote it and the
-- sheet's today when it was written.
CREATE TABLE claim_comment (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    claim_id     BIGINT NOT NULL REFERENCES claim (id),
    by_user      VARCHAR(100) NOT NULL,
    comment_date DATE NOT NULL,
    text         VARCHAR(1000) NOT NULL
);
CREATE INDEX claim_comment_claim ON claim_comment (claim_id);
== V61__claim_edited_by.sql
-- Who last edited a claim; null while it has never been edited. Like its opener, the user who last
-- edited a claim cannot settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(100);
== V62__settle_batch.sql
-- A bulk settle that settles (or leaves PENDING) at least one claim is a batch, numbered 1, 2, ... on
-- its sheet. A claim keeps the number of the batch that settled it (null when settled one at a time,
-- or not settled); the sheet keeps the number of its last batch (null while it has had none).
ALTER TABLE claim ADD COLUMN settle_batch INTEGER;
ALTER TABLE sheet ADD COLUMN last_settle_batch INTEGER;
== V63__person_contact.sql
-- A person's contact: kept without surrounding spaces and in lower case, unique on the sheet; null
-- when they have none.
ALTER TABLE person ADD COLUMN contact VARCHAR(200);
CREATE UNIQUE INDEX person_sheet_contact ON person (sheet_id, contact);
== V64__person_alias.sql
-- A person's aliases: other names they go by. Each is kept without the spaces around it; alias_key
-- is the alias as names are compared (in lower case), and no alias equals any name or alias on the
-- person's sheet.
CREATE TABLE person_alias (
    person_id BIGINT       NOT NULL REFERENCES person (id)

file.content:
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
== V1__sheet.sql
-- A sheet: everything else in the app is kept per sheet, keyed by its id.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP    NOT NULL
);
== V2__sheet_today.sql
-- Each sheet's own "today": every date-dependent decision and default date uses it, never the
-- real clock. It starts as the real date the sheet was first loaded.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- People on a sheet, listed in the order they were added (their id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on its sheet, compared without regard to case and ignoring the spaces
-- around it. Names are kept with those spaces removed; name_key is the name as compared.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200);
UPDATE person SET name_key = LOWER(name);
ALTER TABLE person ALTER COLUMN name_key SET NOT NULL;
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== V5__claim.sql
-- Claims a person makes, listed under the person newest first (their id). The amount is 0.00 or
-- more with up to two decimals; the date defaults to the sheet's today; the note may be empty.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(500)   NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
CREATE INDEX claim_person ON claim (person_id, id);
== V6__rate.sql
-- Each sheet's rate for a grade: a percent, 0.00 or more with two decimals. A grade with no row has
-- no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL,
    pct      DECIMAL(7, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
== V7__claim_status.sql
-- A claim's status: DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID.
-- Only OPEN and SETTLED claims count toward what is claimed and due.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_status CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
== V8__claim_number.sql
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), never reused.
-- A DRAFT claim has none; voiding a claim clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
ALTER TABLE claim ADD CONSTRAINT claim_number_unique UNIQUE (sheet_id, claim_number);
== V9__claim_settled_due.sql
-- What was due on a claim when it was settled, at its person's rate then; later rate changes leave
-- it as it is. Null until the claim is settled, and when its person's grade had no rate then (no
-- figure is fixed, so what is due on it follows the rate).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(12, 2);
== V10__rate_from.sql
-- A rate applies from its from-date on; a rate with no from-date applies from the beginning of
-- time. A grade may have several rates, one per from-date (one with none).
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE UNIQUE NULLS NOT DISTINCT INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_date);
== V11__claim_opened_by.sql
-- Who opened a claim; null while it has not been opened. The user who opened a claim cannot settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
== V12__person_version.sql
-- The version of a person, raised each time they are saved, so an editor that loaded an older
-- version is refused instead of overwriting another user's save.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
== V13__claim_stated.sql
-- Whether a claim is bound to the figure it had at its person's last statement, and that figure.
-- A bound claim shows and totals stated_due whatever later rate or grade changes would make it,
-- until the person's next statement rebinds (or, when the claim no longer counts, unbinds) it.
-- stated_due is null when the claim is unbound, and when it had no figure (no rate) when stated.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(12, 2);
== V14__statement.sql
-- The statements taken of a person: the sheet's today when each was taken, the person's due-total
-- then and how many of their claims counted toward it.
CREATE TABLE statement (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id      BIGINT         NOT NULL REFERENCES person (id),
    statement_date DATE           NOT NULL,
    due_total      DECIMAL(14, 2) NOT NULL,
    claim_count    INT            NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet_id, id);
== V15__statement_due_total_none.sql
-- A statement's due-total is null when the person's due-total was n/a then (no claim with a figure
-- and no rate of their grade in force on the sheet's today).
ALTER TABLE statement ALTER COLUMN due_total SET NULL;
== V16__period.sql
-- A sheet's periods: a name, unique on the sheet without regard to case (name_key is the name as
-- compared), and a from and to date, both inclusive. No two periods of a sheet overlap.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    name_key  VARCHAR(100) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
== V17__period_closed.sql
-- Whether a period is closed, and its due-total fixed when it was closed; later rate changes leave
-- that total as it is. No claim dated in a closed period can be added, edited or change status.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(12, 2);
== V18__person_retired.sql
-- The date a person is retired from; null while they are not retired. A person with the date set
-- is retired at once, whatever the date; claims dated after it are refused.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V19__person_held.sql
-- Whether a person is on hold. While held, their OPEN claims count in no live total (their own,
-- the sheet's or a period's); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
== V20__roles_clerk_limit.sql
-- The role each user name has on a sheet: CLERK or STEWARD. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('CLERK', 'STEWARD'))
);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);

-- The most a clerk may settle a claim for: its due must be at or below it. Null means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(12, 2) CHECK (clerk_limit >= 0);
== V21__sheet_floor.sql
-- The least a claim's live due can be: a due worked out at a rate below it is raised to it. A
-- figure already fixed (settled, bound by a statement, a closed period's total) is left as it was.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(12, 2) DEFAULT 1.00 NOT NULL CHECK (due_floor >= 0);
== V22__sheet_terms.sql
-- The sheet's terms: how many days after its date a claim is due by. An OPEN claim whose due-by is
-- before the sheet's today is overdue.
ALTER TABLE sheet ADD COLUMN terms INTEGER DEFAULT 14 NOT NULL CHECK (terms >= 0);
== V23__sheet_late_pct.sql
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every full
-- 30 days it is overdue. A settled claim keeps the charge it had when it was settled.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(12, 2) DEFAULT 0.00 NOT NULL CHECK (late_pct >= 0);
== V24__person_patron.sql
-- The patrons a person has named: other people on the same sheet, each at most once.
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CONSTRAINT person_patron_unique UNIQUE (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
== V25__person_grade_dated.sql
-- The grades a person has been given, each from a date: the one with the latest from-date on or
-- before a date is in force then; the first one given (no from-date) applies from the beginning of time.
CREATE TABLE person_grade (
    person_id  BIGINT     NOT NULL REFERENCES person (id),
    grade      VARCHAR(1) NOT NULL,
    grade_from DATE
);
CREATE INDEX person_grade_person ON person_grade (person_id);
INSERT INTO person_grade (person_id, grade, grade_from) SELECT id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
== V26__claim_corrects.sql
-- A claim with a negative amount is a correction: it carries in corrects the number of the SETTLED
-- claim of the same person it corrects; corrects is null on any other claim.
ALTER TABLE claim ADD COLUMN corrects INTEGER;

-- The amount was checked to be 0.00 or more by an unnamed constraint: replace the column (which drops
-- that constraint) so only a correction can be negative.
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(12, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_amount_correction CHECK (amount >= 0 OR corrects IS NOT NULL);
== V27__sheet_policy_date.sql
-- The sheet's policy date: a claim dated before it rounds its live figures half up, one dated on or
-- after it half to even (a correction by the date of the claim it corrects). Null means the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
== V28__period_numbering.sql
-- The sheet's period numbering from: while it is set and the sheet's today is on or after it, a claim
-- opened is numbered within the period its date falls in (<period name>-<n>), or X-<n> when it falls in
-- none. Null means off. Claim numbers (and the numbers corrections name) are therefore text.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(120);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(120);

-- The last number given in each per-period sequence of a sheet: seq_key is period:<period id>, or none
-- for the claims dated in no period.
CREATE TABLE claim_sequence (
    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet (id),
    seq_key     VARCHAR(40)  NOT NULL,
    last_number INT          NOT NULL,
    PRIMARY KEY (sheet_id, seq_key)
);
== V29__claim_pending.sql
-- A clerk's settle of a claim whose due is above the clerk limit leaves it PENDING until a steward
-- approves it (SETTLED) or rejects it (back to OPEN). A PENDING claim counts like an OPEN one.
ALTER TABLE claim DROP CONSTRAINT claim_status;
ALTER TABLE claim ADD CONSTRAINT claim_status CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
== V30__claim_listed.sql
-- A claim's place in its sheet's list, newest first: the claims are listed by it, highest first. A
-- claim is given the next value of its sheet's listed sequence when it is added, and again when it is
-- moved to another person, so a moved claim is listed as its new person's newest whatever its date.
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;

-- Start each sheet's listed sequence above the claims it already has.
INSERT INTO claim_sequence (sheet_id, seq_key, last_number)
    SELECT sheet_id, 'listed', MAX(id) FROM claim GROUP BY sheet_id;
== V31__grade_terms_claim_due_by.sql
-- A grade's own terms on a sheet: how many days after its date a claim of a person of that grade is
-- due by. A grade with no row uses the sheet's terms.
CREATE TABLE sheet_grade_terms (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL,
    terms    INTEGER      NOT NULL CHECK (terms >= 0)
);
CREATE UNIQUE INDEX sheet_grade_terms_sheet_grade ON sheet_grade_terms (sheet_id, grade);

-- A claim's due-by, fixed when it is added: its date plus the terms of its person's grade in force
-- on that date. It does not follow later changes to the terms or to the claim's date. The claims
-- already kept are given their date plus their sheet's terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = c.sheet_id), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V32__claim_log.sql
-- A claim's status log: one line per status it has had, in the order it had them, with the user who
-- made the change, the sheet's today then and what was due on the claim as it showed then (null when
-- it had no figure). Claims added before the log was kept start with no lines.
CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    claim_id  BIGINT         NOT NULL REFERENCES claim (id),
    status    VARCHAR(20)    NOT NULL,
    by_user   VARCHAR(100)   NOT NULL,
    log_date  DATE           NOT NULL,
    due       DECIMAL(14, 2)
);
CREATE INDEX claim_log_claim ON claim_log (claim_id, id);
== V33__person_hold_interval.sql
-- The holds a person has been put on, each from a date and, optionally, to one (both included): an
-- OPEN or PENDING claim of theirs dated within a hold counts in no live total, unless a statement
-- binds it. A person held before holds had dates keeps a hold from the beginning of time, with no end.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    hold_from DATE   NOT NULL,
    hold_to   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, hold_from, hold_to) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V34__rate_to.sql
-- A rate may also have a to-date: it applies through it (included). A rate with none applies on with
-- no end.
ALTER TABLE rate ADD COLUMN to_date DATE;
== V35__sheet_cap.sql
-- The most a person's due-total can be: a sum of their figures above it shows the cap, and the
-- difference as their excess. Null means no cap.
ALTER TABLE sheet ADD COLUMN due_cap DECIMAL(12, 2) CHECK (due_cap >= 0);
== V36__period_person_total.sql
-- Each person's due-total for a closed period, fixed when it was closed: what is due on their
-- counting claims dated in it. A person with no row here shows 0.00 for the closed period. The
-- rows are removed when the period is reopened.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    total     DECIMAL(12, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
== V37__sheet_setting_dated.sql
-- A sheet's settings that carry a figure, each recorded from a date: the floor, the late percent, the
-- terms (the sheet's, and each grade's as terms-<grade>), the clerk limit and the cap. The value in
-- force on a date is the one with the latest from-date on or before it; before every from-date it is
-- the sheet's starting value (floor 1.00, late percent 0.00, terms 14; none for the others). A null
-- value records "none" from that date: no clerk limit, no cap, or a grade using the sheet's terms.
CREATE TABLE sheet_setting (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(20)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(20)
);
CREATE UNIQUE INDEX sheet_setting_sheet_key_from ON sheet_setting (sheet_id, setting_key, from_date);

-- The values already kept are in force from the beginning of time.
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'floor', DATE '0001-01-01', CAST(due_floor AS VARCHAR) FROM sheet WHERE due_floor <> 1.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'late-pct', DATE '0001-01-01', CAST(late_pct AS VARCHAR) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'terms', DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet WHERE terms <> 14;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'clerk-limit', DATE '0001-01-01', CAST(clerk_limit AS VARCHAR) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'cap', DATE '0001-01-01', CAST(due_cap AS VARCHAR) FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, 'terms-' || grade, DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet_grade_terms;

DROP TABLE sheet_grade_terms;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN terms;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN due_cap;
== V38__claim_deferred.sql
-- The date an OPEN claim is deferred until: until the sheet's today reaches it the claim counts in no
-- total, is not overdue, cannot be settled and no statement binds it. Null on a claim never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V39__claim_proofs.sql
-- How many proofs a claim has been given; raised by one at a time while it is neither SETTLED nor VOID.
-- The sheet's proof threshold is a dated setting (proof-threshold) kept in sheet_setting.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
== V40__sheet_permission.sql
-- The sheet's permission matrix: for an action (open, settle, void, reassign, close, reopen), the roles
-- that may take it, as a comma separated list of lower-case roles. Not dated. An action with no row, or
-- a blank list, keeps the standing rule: open, settle, void and close by clerk and steward; reassign and
-- reopen by steward.
CREATE TABLE sheet_permission (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    perm_action VARCHAR(20)  NOT NULL,
    roles     VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX sheet_permission_sheet_action ON sheet_permission (sheet_id, perm_action);
== V41__role_viewer.sql
-- A third role, VIEWER: sees the sheet and may change nothing. The role's check is rebuilt to allow it.
CREATE TABLE sheet_role_new (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('CLERK', 'STEWARD', 'VIEWER'))
);
INSERT INTO sheet_role_new (id, sheet_id, user_name, role) SELECT id, sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
ALTER TABLE sheet_role ALTER COLUMN id RESTART WITH (SELECT COALESCE(MAX(id), 0) + 1 FROM sheet_role);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);
== V42__sheet_grace_days.sql
-- The sheet's grace days: when its today is changed, every open period whose to-date plus them is
-- before the new today is closed. Null means off.
ALTER TABLE sheet ADD COLUMN grace_days INTEGER;
== V43__claim_split_from.sql
-- A claim split off another carries in split_from the number of the claim it was split from; null on
-- any other claim.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(120);
== V44__person_watch.sql
-- The people each user watches on a sheet, each at most once per user, in the order they started
-- watching: a watched person's claim settled, approved or re-settled notifies each watcher.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(100) NOT NULL,
    CONSTRAINT person_watch_unique UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
== V45__sheet_delegation.sql
-- The steward role delegated by a steward to a user on a sheet, from a from-date to a to-date
-- inclusive: while the sheet's today is inside the range the user acts as a steward.
CREATE TABLE sheet_delegation (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    delegator VARCHAR(100) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (to_date >= from_date)
);
CREATE INDEX sheet_delegation_sheet_user ON sheet_delegation (sheet_id, user_name);
== V46__sheet_archived.sql
-- Whether the sheet is archived: once it is, every change asked of it is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
== V47__person_terms.sql
-- A person's own terms: how many days after its date a claim of theirs is due by, in place of the
-- terms of their grade and the sheet's; null when they have none.
ALTER TABLE person ADD COLUMN terms INTEGER CHECK (terms >= 0);
== V48__claim_lock.sql
-- A claim's editor, once opened, locks the claim for other users: locked_by is the user holding it and
-- locked_on the sheet's today when it was taken. Null while no one holds it; saving or cancelling the
-- editor, or changing the sheet's today, releases it.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(100);
ALTER TABLE claim ADD COLUMN locked_on DATE;
== V49__period_soft_close.sql
-- Whether a closed period is only soft-closed: its due-total and each person's figure for it are fixed
-- as for a close, but claims dated in it can still be added, edited and change status. A claim added
-- while its period is soft-closed is a late entry.
ALTER TABLE period ADD COLUMN soft BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
== V50__claim_stated_by.sql
-- The statement that bound a claim to stated_due; null while the claim is unbound. Cancelling a
-- person's last statement unbinds the claims it bound.
ALTER TABLE claim ADD COLUMN stated_by BIGINT;
== V51__sheet_history.sql
-- Every change to what a sheet's figures are made of (its people, claims, rates, dated settings and
-- the sheet itself), one line per row as it stood after the change, in the order they happened, with
-- the sheet's today when it was made; state is null when the row was removed. A sheet's state as of a
-- date is, for each row, its last line made on or before that date.
CREATE TABLE sheet_history (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL,
    made_on   DATE         NOT NULL,
    entity    VARCHAR(30)  NOT NULL,
    entity_id VARCHAR(100) NOT NULL,
    state     CLOB
);
CREATE INDEX sheet_history_sheet ON sheet_history (sheet_id, made_on, id);
== V52__sheet_entry_date.sql
-- The sheet's entry date: while it is set, a claim added or edited without a date is dated it rather
-- than the sheet's today; null when it is off.
ALTER TABLE sheet ADD COLUMN entry_date DATE;
== V53__claim_reminded.sql
-- The sheet's today on which a reminder was last written for the claim; null when none ever was.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
== V54__sheet_holiday.sql
-- The holidays on a sheet, one row each: a claim's due-by fixed when it is added is moved past them.
CREATE TABLE sheet_holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL,
    CONSTRAINT sheet_holiday_unique UNIQUE (sheet_id, holiday_date)
);
== V55__claim_business_day_terms.sql
-- A claim's terms now count business days. Each claim keeps the terms it was fixed with and the date
-- its due-by counts from (its date when it was added); its due-by is the terms-th business day after
-- that date, skipping weekends and the sheet's holidays. The claims already kept count from their date,
-- with the days their due-by was fixed after it; V56 works their due-by out again in business days.
ALTER TABLE claim ADD COLUMN due_from DATE;
ALTER TABLE claim ADD COLUMN terms INTEGER;
UPDATE claim SET due_from = claim_date, terms = GREATEST(0, DATEDIFF(DAY, claim_date, due_by));
ALTER TABLE claim ALTER COLUMN due_from SET NOT NULL;
ALTER TABLE claim ALTER COLUMN terms SET NOT NULL;
== V57__claim_ref.sql
-- A claim's external reference: null when it has none. Unique on the sheet without regard to case
-- (ref_key is the reference as compared).
ALTER TABLE claim ADD COLUMN ref VARCHAR(120);
ALTER TABLE claim ADD COLUMN ref_key VARCHAR(120);
CREATE UNIQUE INDEX claim_sheet_ref ON claim (sheet_id, ref_key);
== V58__claim_tags.sql
-- A claim's tags: trimmed, lower-cased, without repeats, sorted and comma separated; null when it has
-- none. sheet_tag keeps every tag ever used on a sheet's claims.
ALTER TABLE claim ADD COLUMN tags VARCHAR(1000);
CREATE TABLE sheet_tag (
    sheet_id VARCHAR(100) NOT NULL,
    tag      VARCHAR(500) NOT NULL,
    PRIMARY KEY (sheet_id, tag)
);
== V59__void_reason.sql
-- The reasons a claim can be voided with on a sheet, one row each; while a sheet has any, a void of
-- one of its claims names one of them, kept on the claim (null on a claim voided without one).
CREATE TABLE sheet_void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(200) NOT NULL,
    CONSTRAINT sheet_void_reason_unique UNIQUE (sheet_id, reason)
);
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
== V60__claim_comment.sql
-- A claim's comments, one row each, oldest first by id: the text, the user who wrote it and the
-- sheet's today when it was written.
CREATE TABLE claim_comment (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    claim_id     BIGINT NOT NULL REFERENCES claim (id),
    by_user      VARCHAR(100) NOT NULL,
    comment_date DATE NOT NULL,
    text         VARCHAR(1000) NOT NULL
);
CREATE INDEX claim_comment_claim ON claim_comment (claim_id);
== V61__claim_edited_by.sql
-- Who last edited a claim; null while it has never been edited. Like its opener, the user who last
-- edited a claim cannot settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(100);
== V62__settle_batch.sql
-- A bulk settle that settles (or leaves PENDING) at least one claim is a batch, numbered 1, 2, ... on
-- its sheet. A claim keeps the number of the batch that settled it (null when settled one at a time,
-- or not settled); the sheet keeps the number of its last batch (null while it has had none).
ALTER TABLE claim ADD COLUMN settle_batch INTEGER;
ALTER TABLE sheet ADD COLUMN last_settle_batch INTEGER;
== V63__person_contact.sql
-- A person's contact: kept without surrounding spaces and in lower case, unique on the sheet; null
-- when they have none.
ALTER TABLE person ADD COLUMN contact VARCHAR(200);
CREATE UNIQUE INDEX person_sheet_contact ON person (sheet_id, contact);
== V64__person_alias.sql
-- A person's aliases: other names they go by. Each is kept without the spaces around it; alias_key
-- is the alias as names are compared (in lower case), and no alias equals any name or alias on the
-- person's sheet.
CREATE TABLE person_alias (
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) NOT NULL
);
CREATE INDEX person_alias_person ON person_alias (person_id);
CREATE INDEX person_alias_key ON person_alias (alias_key);
== V65__claim_template.sql
-- The claim templates on a sheet, one row each by name: a template's amount and note are copied into
-- a DRAFT claim added from it, so a template changed or saved again later leaves those claims as they were.
CREATE TABLE sheet_claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200)   NOT NULL,
    amount   DECIMAL(12, 2) NOT NULL,
    note     VARCHAR(500)   NOT NULL,
    CONSTRAINT sheet_claim_template_unique UNIQUE (sheet_id, name)
);
== V66__pool.sql
-- The pools on a sheet, one row each by name (kept without the spaces around it).
CREATE TABLE sheet_pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    CONSTRAINT sheet_pool_unique UNIQUE (sheet_id, name)
);
-- A pool's members: people on the pool's sheet, each at most once per pool, with their share percent
-- (more than 0.00 and at most 100.00). A person can be in several pools.
CREATE TABLE sheet_pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT       NOT NULL REFERENCES sheet_pool (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL,
    CONSTRAINT sheet_pool_member_unique UNIQUE (pool_id, person_id)
);
== V67__sheet_pot.sql
-- The sheet's pot, shared out among the members of each balanced pool by their shares; null when
-- there is none. Not dated.
ALTER TABLE sheet ADD COLUMN pot DECIMAL(12, 2) CHECK (pot >= 0);
== V68__sheet_parent.sql
-- The sheet's parent: the sheet whose rates (then its parent's, up to three levels up) are used for a
-- grade and date that have no rate in force on this sheet; null when there is none. Not dated.
ALTER TABLE sheet ADD COLUMN parent_id VARCHAR(100);
== V69__claim_deleted.sql
-- A DRAFT claim can be DELETED (and restored to DRAFT on the same sheet-today).
ALTER TABLE claim DROP CONSTRAINT claim_status;
ALTER TABLE claim ADD CONSTRAINT claim_status CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'DELETED'));
== V70__pool_member_pool.sql
-- A pool's member may be another pool on the same sheet instead of a person: exactly one of person_id and
-- member_pool_id is set. A pool is a member of at most one pool.
ALTER TABLE sheet_pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE sheet_pool_member ADD COLUMN member_pool_id BIGINT REFERENCES sheet_pool (id);
ALTER TABLE sheet_pool_member ADD CONSTRAINT sheet_pool_member_one
    CHECK ((person_id IS NULL) <> (member_pool_id IS NULL));
ALTER TABLE sheet_pool_member ADD CONSTRAINT sheet_pool_member_pool_unique UNIQUE (member_pool_id);
== V71__person_position.sql
-- A person's place in the sheet's list: people are listed by it, new people go to the end.
ALTER TABLE person ADD COLUMN list_position BIGINT;
UPDATE person SET list_position = id;
ALTER TABLE person ALTER COLUMN list_position SET NOT NULL;
== V72__person_origin.sql
-- The sheet a transferred person came from; null for anyone else.
ALTER TABLE person ADD COLUMN origin_sheet_id VARCHAR(100);
== V73__pool_member_dated.sql
-- A pool membership may carry a from-date and a to-date (both optional, the to-date not before the from-date); a
-- member whose dates do not include the sheet's today is left out of the pool's total share, balance and cuts.
ALTER TABLE sheet_pool_member ADD COLUMN from_date DATE;
ALTER TABLE sheet_pool_member ADD COLUMN to_date DATE;
== V74__person_retirement.sql
-- The past retirements of a person who was unretired, each from its from-date to the day they were
-- unretired: a claim of theirs dated after the from-date and before the to-date is refused.
